import { RateLimiterRedis } from 'rate-limiter-flexible'
const limiter = new RateLimiterRedis({ storeClient: redis, points: 100, duration: 60 })
try { await limiter.consume(userId, cost) }        // cost-weighted metering
catch (rejection) {
  res.status(429)
     .set('Retry-After', String(Math.ceil(rejection.msBeforeNext / 1000)))
     .end()
}
